import { readdirSync, writeFileSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = fileURLToPath(new URL(".", import.meta.url));
const packageRoot = resolve(scriptDir, "..");
const iconsDir = join(packageRoot, "src", "icons");
const outputFile = join(iconsDir, "Icon.tsx");
const generatedHeader =
  "// Generated by packages/ui/scripts/generate-icons.js. Do not edit manually.\n";

const toIconName = (componentName) => {
  const baseName = componentName.replace(/Icon$/, "");

  return baseName.charAt(0).toLowerCase() + baseName.slice(1);
};

const getIconComponents = () => {
  return readdirSync(iconsDir)
    .filter((fileName) => fileName.endsWith("Icon.tsx"))
    .filter((fileName) => fileName !== "Icon.tsx")
    .map((fileName) => basename(fileName, ".tsx"))
    .sort((firstComponent, secondComponent) => firstComponent.localeCompare(secondComponent));
};

const toIconComponentFile = (components) => {
  const imports = components
    .map((componentName) => `import { ${componentName} } from "./${componentName}";`)
    .join("\n");
  const registryEntries = components
    .map((componentName) => `  ${toIconName(componentName)}: ${componentName},`)
    .join("\n");

  return `${generatedHeader}import { Cell, If } from "retend";
import { useDerivedAsyncValue } from "retend-utils/hooks";
import type { JSX } from "retend/jsx-runtime";

${imports}
import type { SVGProps } from "./Svg";

const icons = {
${registryEntries}
} as const;

export type IconName = keyof typeof icons;

/** Whether a name from data (a provider's icon, say) has an icon here. */
export function isIconName(name: string): name is IconName {
  return Object.hasOwn(icons, name);
}

interface IconNameProps {
  name: JSX.ValueOrCellOrPromise<IconName>;
}

export type IconProps = SVGProps & IconNameProps;

export function Icon(props: IconProps) {
  const { name: nameProp, ...svgProps } = props;
  const name = useDerivedAsyncValue(nameProp);

  const IconComponent = Cell.derivedAsync(async (get) => {
    const iconName: IconName = await get(name);
    return icons[iconName];
  });

  return If(IconComponent, (Component) => {
    return <Component {...svgProps} />;
  });
}
`;
};

const generateIconComponent = () => {
  const components = getIconComponents();

  if (components.length === 0) {
    throw new Error(`No icon components found in: ${iconsDir}`);
  }

  writeFileSync(outputFile, toIconComponentFile(components));
  console.log(`Generated Icon component with ${components.length} icons`);
};

generateIconComponent();
